from langflow.custom import Component
from langflow.io import Output, DataInput, TableInput
from langflow.schema import Data, Message
from typing import Any
import json

class SafeFallback(str):
    """
    Helper class untuk mengembalikan string kosong secara aman 
    ketika mencoba mengakses atribut atau index pada data yang terdalam.
    """
    def __getattr__(self, name: str) -> 'SafeFallback':
        return SafeFallback("")

    def __getitem__(self, key: Any) -> 'SafeFallback':
        return SafeFallback("")

class DeepParsedDict(dict):
    """
    Dictionary wrapper yang mengubah dictionary biasa menjadi object 
    yang mendukung dot-notation bersarang dengan kedalaman tak terbatas.
    """
    def __init__(self, data_map: dict):
        super().__init__()
        if not isinstance(data_map, dict):
            return

        for k, v in data_map.items():
            if isinstance(v, dict):
                self[k] = DeepParsedDict(v)
            elif isinstance(v, list):
                self[k] = [DeepParsedDict(i) if isinstance(i, dict) else i for i in v]
            else:
                self[k] = v

    def __getattr__(self, key: str) -> Any:
        val = self.get(key)
        return SafeFallback("") if val is None else val

    def __missing__(self, key: str) -> Any:
        return SafeFallback("")


class AstraDynamicParserFilterComponent(Component):
    display_name = "Dynamic Parser"
    description = "Menerima input lalu membangun filter secara dinamis. Mendukung dynamic key & value, dengan output JSON, Data (Table), atau Message."
    icon = "table"

    inputs = [
        DataInput(
            name="input_data",
            display_name="Input Data (Upstream)",
            info="Hubungkan node sebelumnya di sini (Data, Message, dict, list/tabel, DataFrame, atau string JSON).",
            # Menambahkan 'list' dan 'DataFrame' agar Langflow bisa menerima tabel
            input_types=["Message", "Data", "dict", "str", "list", "DataFrame"],
            required=False,
        ),
        TableInput(
            name="filter_table",
            display_name="Filter Parameters",
            info="Kini Key dan Value mendukung parser template bersarang! (contoh: {kategori}, {tabel.0.id}, atau {user.id}).",
            table_schema=[
                {
                    "name": "key",
                    "display_name": "Metadata Key",
                    "type": "str",
                    "description": "Nama field metadata (Bisa statis atau dinamis seperti {kategori}_id)",
                },
                {
                    "name": "value",
                    "display_name": "Metadata Value",
                    "type": "str",
                    "description": "Nilai statis atau parser template (misal: {status})",
                },
            ],
            value=[],
            is_list=True,
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="JSON Dict", name="json_output", method="build_json"),
        Output(display_name="Table (Data)", name="data_output", method="build_data"),
        Output(display_name="Message Text", name="message_output", method="build_message"),
    ]

    def _extract_source_data(self) -> dict:
        source_dict = {}
        target_input = self.input_data

        if not target_input:
            return source_dict

        # 1. Pre-processing: Deteksi & Parse JSON otomatis jika input berupa String
        if isinstance(target_input, str):
            target_input_stripped = target_input.strip()
            if target_input_stripped.startswith(("{", "[")):
                try:
                    target_input = json.loads(target_input_stripped)
                except Exception:
                    pass # Abaikan jika gagal parse, biarkan tetap sebagai string

        # 2. Pattern Matching ala Langflow terbaru untuk mengekstrak data
        match target_input:
            case list():
                # Simpan list/tabel utuh agar bisa diakses menggunakan {tabel} atau {list}
                source_dict["tabel"] = target_input
                source_dict["list"] = target_input

                # Ekstrak elemen pertama ke root agar variabelnya bisa dipanggil langsung (backward compatibility)
                if len(target_input) > 0:
                    first_item = target_input[0]
                    if hasattr(first_item, "data") and isinstance(first_item.data, dict):
                        source_dict.update(first_item.data)
                    elif isinstance(first_item, dict):
                        source_dict.update(first_item)

            case _ if type(target_input).__name__ == "DataFrame":
                # Convert Pandas DataFrame ke format list of dict
                records = target_input.to_dict(orient="records")
                source_dict["tabel"] = records
                source_dict["list"] = records
                if records:
                    source_dict.update(records[0])

            case _ if hasattr(target_input, "data") and isinstance(target_input.data, dict):
                # Objek Data bawaan Langflow
                source_dict.update(target_input.data)
                source_dict["data"] = dict(target_input.data)

            case dict():
                # Objek Dictionary murni
                source_dict.update(target_input)

            case str():
                # Jika murni teks
                source_dict["text"] = target_input

            case _:
                # Message Object fallback
                if hasattr(target_input, "text") and isinstance(target_input.text, str):
                    source_dict["text"] = target_input.text
                elif hasattr(target_input, "content") and isinstance(target_input.content, str):
                    source_dict["text"] = target_input.content

        # 3. Fallback: Pastikan 'prompt' tersedia jika ada 'text'
        if "text" in source_dict and "prompt" not in source_dict:
            source_dict["prompt"] = source_dict["text"]

        return source_dict

    def _generate_parsed_dict(self) -> dict:
        """
        Fungsi inti yang merangkai dan mem-parsing Key serta Value.
        """
        source_data = self._extract_source_data()
        formatted_source = DeepParsedDict(source_data)
        result_filter = {}

        if not self.filter_table:
            return result_filter

        for row in self.filter_table:
            if isinstance(row, dict) and "key" in row and "value" in row:
                raw_k = str(row.get("key") or "").strip()
                v = row.get("value", "")

                if not raw_k:
                    continue

                # 1. Parsing dinamis untuk KEY
                k = raw_k
                if "{" in k and "}" in k:
                    try:
                        k = k.format_map(formatted_source)
                    except Exception as e:
                        print(f"Error memproses parser Key '{raw_k}': {e}")
                        k = raw_k

                k = k.strip()
                # Jika setelah diparsing key ternyata kosong, lewati baris ini
                if not k:
                    continue

                # 2. Parsing dinamis untuk VALUE
                formatted_val = v
                if isinstance(v, str):
                    v_trimmed = v.strip()
                    if "{" in v_trimmed and "}" in v_trimmed:
                        try:
                            formatted_val = v_trimmed.format_map(formatted_source)
                        except Exception as e:
                            print(f"Error memproses parser Value '{v_trimmed}': {e}")
                            formatted_val = v_trimmed

                    # Konversi otomatis tipe data untuk Value
                    if isinstance(formatted_val, str):
                        val_lower = formatted_val.lower()
                        if val_lower == "true":
                            formatted_val = True
                        elif val_lower == "false":
                            formatted_val = False
                        elif val_lower in ("null", "none"):
                            formatted_val = None
                        elif formatted_val.isdigit():
                            formatted_val = int(formatted_val)

                result_filter[k] = formatted_val

        print(f"[Astra Filter] Hasil akhir parsing: {result_filter}")
        return result_filter

    # ==========================================
    # OUTPUT ROUTERS
    # ==========================================
    def build_json(self) -> dict:
        """Output 1: Raw Dictionary (JSON) standar Python."""
        return self._generate_parsed_dict()

    def build_data(self) -> Data:
        """Output 2: Objek Data (Table Langflow). Berguna untuk manipulasi tabel."""
        parsed_dict = self._generate_parsed_dict()
        return Data(data=parsed_dict)

    def build_message(self) -> Message:
        """Output 3: Objek Message. Berguna jika ingin dikirim langsung ke LLM/Prompt."""
        parsed_dict = self._generate_parsed_dict()
        # Ubah dict menjadi string JSON agar cantik dibaca jika dilempar sebagai pesan
        text_content = json.dumps(parsed_dict, indent=2)
        return Message(text=text_content)

import pandas as pd

from lfx.custom.custom_component.component import Component
from lfx.inputs import SortableListInput
from lfx.io import BoolInput, DataFrameInput, DropdownInput, IntInput, MessageTextInput, Output, StrInput
from lfx.log.logger import logger
from lfx.schema.dataframe import DataFrame


class DataFrameOperationsComponent(Component):
    display_name = "Table Operations"
    description = "Perform various operations on a Table."
    documentation: str = "https://docs.langflow.org/dataframe-operations"
    icon = "table"
    name = "DataFrameOperations"
    legacy = True
    replacement = ["processing.Operations"]
    metadata = {
        "keywords": [
            "dataframe",
            "dataframe operations",
            "table",
            "table operations",
            "filter",
            "sort",
            "merge",
            "concatenate",
            "drop column",
            "rename column",
            "add column",
            "select columns",
            "replace value",
            "drop duplicates",
        ],
    }

    OPERATION_CHOICES = [
        "Add Column",
        "Concatenate",
        "Drop Column",
        "Filter",
        "Head",
        "Merge",
        "Rename Column",
        "Replace Value",
        "Select Columns",
        "Sort",
        "Tail",
        "Drop Duplicates",
    ]

    inputs = [
        DataFrameInput(
            name="df",
            display_name="Table",
            info="The input DataFrame to operate on. Connect multiple DataFrames for merge or concatenate operations.",
            required=True,
            is_list=True,
        ),
        SortableListInput(
            name="operation",
            display_name="Operation",
            placeholder="Select Operation",
            info="Select the DataFrame operation to perform.",
            options=[
                {"name": "Add Column", "icon": "plus"},
                {"name": "Concatenate", "icon": "combine"},
                {"name": "Drop Column", "icon": "minus"},
                {"name": "Filter", "icon": "filter"},
                {"name": "Head", "icon": "arrow-up"},
                {"name": "Merge", "icon": "merge"},
                {"name": "Rename Column", "icon": "pencil"},
                {"name": "Replace Value", "icon": "replace"},
                {"name": "Select Columns", "icon": "columns"},
                {"name": "Sort", "icon": "arrow-up-down"},
                {"name": "Tail", "icon": "arrow-down"},
                {"name": "Drop Duplicates", "icon": "copy-x"},
            ],
            real_time_refresh=True,
            limit=1,
        ),
        StrInput(
            name="column_name",
            display_name="Column Name",
            info="The column name to use for the operation.",
            dynamic=True,
            show=False,
        ),
        MessageTextInput(
            name="filter_value",
            display_name="Filter Value",
            info="The value to filter rows by.",
            dynamic=True,
            show=False,
        ),
        DropdownInput(
            name="filter_operator",
            display_name="Filter Operator",
            options=[
                "equals",
                "not equals",
                "contains",
                "not contains",
                "starts with",
                "ends with",
                "greater than",
                "less than",
            ],
            value="equals",
            info="The operator to apply for filtering rows.",
            advanced=False,
            dynamic=True,
            show=False,
        ),
        BoolInput(
            name="ascending",
            display_name="Sort Ascending",
            info="Whether to sort in ascending order.",
            dynamic=True,
            show=False,
            value=True,
        ),
        StrInput(
            name="new_column_name",
            display_name="New Column Name",
            info="The new column name when renaming or adding a column.",
            dynamic=True,
            show=False,
        ),
        MessageTextInput(
            name="new_column_value",
            display_name="New Column Value",
            info="The value to populate the new column with.",
            dynamic=True,
            show=False,
        ),
        StrInput(
            name="columns_to_select",
            display_name="Columns to Select",
            dynamic=True,
            is_list=True,
            show=False,
        ),
        IntInput(
            name="num_rows",
            display_name="Number of Rows",
            info="Number of rows to return (for head/tail).",
            dynamic=True,
            show=False,
            value=5,
        ),
        MessageTextInput(
            name="replace_value",
            display_name="Value to Replace",
            info="The value to replace in the column.",
            dynamic=True,
            show=False,
        ),
        MessageTextInput(
            name="replacement_value",
            display_name="Replacement Value",
            info="The value to replace with.",
            dynamic=True,
            show=False,
        ),
        DataFrameInput(
            name="left_dataframe",
            display_name="Left Table",
            info="The left (primary) DataFrame for merge operations. "
            "In a left merge, all rows from this table are preserved.",
            dynamic=True,
            show=False,
        ),
        DataFrameInput(
            name="right_dataframe",
            display_name="Right Table",
            info="The right (secondary) DataFrame for merge operations. "
            "In a right merge, all rows from this table are preserved.",
            dynamic=True,
            show=False,
        ),
        StrInput(
            name="merge_on_column",
            display_name="Merge On Column",
            info="The column name to merge DataFrames on. Must exist in both DataFrames.",
            dynamic=True,
            show=False,
        ),
        DropdownInput(
            name="merge_how",
            display_name="Merge Type",
            options=["inner", "outer", "left", "right"],
            value="inner",
            info="Type of merge: inner (intersection), outer (union), left, or right.",
            dynamic=True,
            show=False,
        ),
    ]

    outputs = [
        Output(
            display_name="Table",
            name="output",
            method="perform_operation",
            info="The resulting DataFrame after the operation.",
        )
    ]

    def update_build_config(self, build_config, field_value, field_name=None):
        dynamic_fields = [
            "column_name",
            "filter_value",
            "filter_operator",
            "ascending",
            "new_column_name",
            "new_column_value",
            "columns_to_select",
            "num_rows",
            "replace_value",
            "replacement_value",
            "left_dataframe",
            "right_dataframe",
            "merge_on_column",
            "merge_how",
        ]
        for field in dynamic_fields:
            build_config[field]["show"] = False

        if field_name == "operation":
            # Handle SortableListInput format
            if isinstance(field_value, list):
                operation_name = field_value[0].get("name", "") if field_value else ""
            else:
                operation_name = field_value or ""

            # If no operation selected, all dynamic fields stay hidden (already set to False above)
            if not operation_name:
                return build_config

            if operation_name == "Filter":
                build_config["column_name"]["show"] = True
                build_config["filter_value"]["show"] = True
                build_config["filter_operator"]["show"] = True
            elif operation_name == "Sort":
                build_config["column_name"]["show"] = True
                build_config["ascending"]["show"] = True
            elif operation_name == "Drop Column":
                build_config["column_name"]["show"] = True
            elif operation_name == "Rename Column":
                build_config["column_name"]["show"] = True
                build_config["new_column_name"]["show"] = True
            elif operation_name == "Add Column":
                build_config["new_column_name"]["show"] = True
                build_config["new_column_value"]["show"] = True
            elif operation_name == "Select Columns":
                build_config["columns_to_select"]["show"] = True
            elif operation_name in {"Head", "Tail"}:
                build_config["num_rows"]["show"] = True
            elif operation_name == "Replace Value":
                build_config["column_name"]["show"] = True
                build_config["replace_value"]["show"] = True
                build_config["replacement_value"]["show"] = True
            elif operation_name == "Drop Duplicates":
                build_config["column_name"]["show"] = True
            elif operation_name == "Merge":
                build_config["left_dataframe"]["show"] = True
                build_config["right_dataframe"]["show"] = True
                build_config["merge_on_column"]["show"] = True
                build_config["merge_how"]["show"] = True

        return build_config

    def _get_primary_dataframe(self) -> DataFrame:
        """Get the first DataFrame from input (handles both single and list inputs)."""
        if isinstance(self.df, list):
            return self.df[0].copy() if self.df else DataFrame()
        return self.df.copy()

    def perform_operation(self) -> DataFrame:
        # Handle SortableListInput format for operation (also supports legacy string format)
        operation_input = getattr(self, "operation", [])
        if isinstance(operation_input, list):
            op = operation_input[0].get("name", "") if operation_input else ""
        else:
            op = operation_input or ""

        # Merge and Concatenate use their own inputs, not the primary df
        if op == "Merge":
            return self.merge_dataframes()
        if op == "Concatenate":
            return self.concatenate_dataframes()

        df_copy = self._get_primary_dataframe()

        # If no operation selected, return original DataFrame
        if not op:
            return df_copy

        if op == "Filter":
            return self.filter_rows_by_value(df_copy)
        if op == "Sort":
            return self.sort_by_column(df_copy)
        if op == "Drop Column":
            return self.drop_column(df_copy)
        if op == "Rename Column":
            return self.rename_column(df_copy)
        if op == "Add Column":
            return self.add_column(df_copy)
        if op == "Select Columns":
            return self.select_columns(df_copy)
        if op == "Head":
            return self.head(df_copy)
        if op == "Tail":
            return self.tail(df_copy)
        if op == "Replace Value":
            return self.replace_values(df_copy)
        if op == "Drop Duplicates":
            return self.drop_duplicates(df_copy)
        msg = f"Unsupported operation: {op}"
        logger.error(msg)
        raise ValueError(msg)

    def filter_rows_by_value(self, df: DataFrame) -> DataFrame:
        column = df[self.column_name]
        filter_value = self.filter_value

        # Handle regular DropdownInput format (just a string value)
        operator = getattr(self, "filter_operator", "equals")  # Default to equals for backward compatibility

        if operator == "equals":
            mask = column == filter_value
        elif operator == "not equals":
            mask = column != filter_value
        elif operator == "contains":
            mask = column.astype(str).str.contains(str(filter_value), na=False)
        elif operator == "not contains":
            mask = ~column.astype(str).str.contains(str(filter_value), na=False)
        elif operator == "starts with":
            mask = column.astype(str).str.startswith(str(filter_value), na=False)
        elif operator == "ends with":
            mask = column.astype(str).str.endswith(str(filter_value), na=False)
        elif operator == "greater than":
            try:
                # Try to convert filter_value to numeric for comparison
                numeric_value = pd.to_numeric(filter_value)
                mask = column > numeric_value
            except (ValueError, TypeError):
                # If conversion fails, compare as strings
                mask = column.astype(str) > str(filter_value)
        elif operator == "less than":
            try:
                # Try to convert filter_value to numeric for comparison
                numeric_value = pd.to_numeric(filter_value)
                mask = column < numeric_value
            except (ValueError, TypeError):
                # If conversion fails, compare as strings
                mask = column.astype(str) < str(filter_value)
        else:
            mask = column == filter_value  # Fallback to equals

        return DataFrame(df[mask])

    def sort_by_column(self, df: DataFrame) -> DataFrame:
        return DataFrame(df.sort_values(by=self.column_name, ascending=self.ascending))

    def drop_column(self, df: DataFrame) -> DataFrame:
        return DataFrame(df.drop(columns=[self.column_name]))

    def rename_column(self, df: DataFrame) -> DataFrame:
        return DataFrame(df.rename(columns={self.column_name: self.new_column_name}))

    def add_column(self, df: DataFrame) -> DataFrame:
        df[self.new_column_name] = [self.new_column_value] * len(df)
        return DataFrame(df)

    def select_columns(self, df: DataFrame) -> DataFrame:
        columns = [col.strip() for col in self.columns_to_select]
        return DataFrame(df[columns])

    def head(self, df: DataFrame) -> DataFrame:
        return DataFrame(df.head(self.num_rows))

    def tail(self, df: DataFrame) -> DataFrame:
        return DataFrame(df.tail(self.num_rows))

    def replace_values(self, df: DataFrame) -> DataFrame:
        df[self.column_name] = df[self.column_name].replace(self.replace_value, self.replacement_value)
        return DataFrame(df)

    def drop_duplicates(self, df: DataFrame) -> DataFrame:
        return DataFrame(df.drop_duplicates(subset=self.column_name))

    def concatenate_dataframes(self) -> DataFrame:
        """Concatenate multiple DataFrames vertically (stack rows)."""
        if not isinstance(self.df, list) or len(self.df) == 0:
            return self.df.copy() if self.df is not None else DataFrame()

        # If only one DataFrame, return it
        if len(self.df) == 1:
            return self.df[0].copy()

        # Concatenate all DataFrames vertically
        concatenated = pd.concat(self.df, ignore_index=True)
        return DataFrame(concatenated)

    def merge_dataframes(self) -> DataFrame:
        """Merge two DataFrames based on a common column (join operation).

        Uses explicit left_dataframe and right_dataframe inputs to give the user
        deterministic control over which DataFrame is primary (left) and which
        is secondary (right) in the merge.
        """
        left_df = getattr(self, "left_dataframe", None)
        right_df = getattr(self, "right_dataframe", None)

        if left_df is None:
            return DataFrame()

        if right_df is None:
            return left_df.copy()

        df_left = left_df.copy()
        df_right = right_df.copy()

        merge_on = getattr(self, "merge_on_column", None)
        merge_how = getattr(self, "merge_how", "inner")

        if merge_on:
            if merge_on not in df_left.columns:
                msg = f"Column '{merge_on}' not found in left DataFrame. Available: {list(df_left.columns)}"
                raise ValueError(msg)
            if merge_on not in df_right.columns:
                msg = f"Column '{merge_on}' not found in right DataFrame. Available: {list(df_right.columns)}"
                raise ValueError(msg)

            merged = df_left.merge(df_right, on=merge_on, how=merge_how, suffixes=("", "_right"))
        else:
            merged = df_left.merge(df_right, left_index=True, right_index=True, how=merge_how, suffixes=("", "_right"))

        # Combine duplicate columns: use left value if exists, otherwise right value
        cols_to_drop = []
        for col in merged.columns:
            if col.endswith("_right"):
                original_col = col[:-6]  # Remove "_right" suffix
                if original_col in merged.columns:
                    merged[original_col] = merged[original_col].combine_first(merged[col])
                    cols_to_drop.append(col)

        if cols_to_drop:
            merged = merged.drop(columns=cols_to_drop)

        return DataFrame(merged)

