    outputs = [
        Output(display_name="API Response", name="data", method="make_api_request"),
    ]

    def _parse_json_value(self, value: Any) -> Any:
        if not isinstance(value, str):
            return value

        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return value
        else:
            return parsed

    def _process_body(self, body: Any) -> dict:
        if body is None:
            return {}
        if hasattr(body, "data"):
            body = body.data
        if isinstance(body, dict):
            return self._process_dict_body(body)
        if isinstance(body, str):
            return self._process_string_body(body)
        if isinstance(body, list):
            return self._process_list_body(body)
        return {}

    def _process_dict_body(self, body: dict) -> dict:
        return {k: self._parse_json_value(v) for k, v in body.items()}

    def _process_string_body(self, body: str) -> dict:
        try:
            return self._process_body(json.loads(body))
        except json.JSONDecodeError:
            return {"data": body}

    def _process_list_body(self, body: list) -> dict:
        processed_dict = {}
        try:
            for item in body:
                current_item = item
                if hasattr(item, "data"):
                    unwrapped_data = item.data
                    if isinstance(unwrapped_data, dict) and not self._is_valid_key_value_item(unwrapped_data):
                        return unwrapped_data
                    current_item = unwrapped_data
                if not self._is_valid_key_value_item(current_item):
                    continue
                key = current_item["key"]
                value = self._parse_json_value(current_item["value"])
                processed_dict[key] = value
        except (KeyError, TypeError, ValueError) as e:
            self.log(f"Failed to process body list: {e}")
            return {}
        return processed_dict

    def _is_valid_key_value_item(self, item: Any) -> bool:
        return isinstance(item, dict) and "key" in item and "value" in item

    def parse_curl(self, curl: str, build_config: dotdict) -> dotdict:
        try:
            parsed = parse_context(curl)
            url = parsed.url
            url = self._normalize_url(url)

            build_config["url_input"]["value"] = url
            build_config["method"]["value"] = parsed.method.upper()

            headers_list = [{"key": k, "value": v} for k, v in parsed.headers.items()]
            build_config["headers"]["value"] = headers_list

            if not parsed.data:
                build_config["body"]["value"] = []
            elif parsed.data:
                try:
                    json_data = json.loads(parsed.data)
                    if isinstance(json_data, dict):
                        body_list = [
                            {"key": k, "value": json.dumps(v) if isinstance(v, dict | list) else str(v)}
                            for k, v in json_data.items()
                        ]
                        build_config["body"]["value"] = body_list
                    else:
                        build_config["body"]["value"] = [{"key": "data", "value": json.dumps(json_data)}]
                except json.JSONDecodeError:
                    build_config["body"]["value"] = [{"key": "data", "value": parsed.data}]

        except Exception as exc:
            msg = f"Error parsing curl: {exc}"
            self.log(msg)
            raise ValueError(msg) from exc

        return build_config

    def _normalize_url(self, url: str) -> str:
        if not url or not isinstance(url, str):
            msg = "URL cannot be empty"
            raise ValueError(msg)

        url = url.strip()
        if url.startswith(("http://", "https://")):
            return url
        return f"https://{url}"

    async def make_request(
        self,
        client: httpx.AsyncClient,
        method: str,
        url: str,
        headers: dict | None = None,
        body: Any = None,
        timeout: int = 5,
        *,
        follow_redirects: bool = False,
        save_to_file: bool = False,
        include_httpx_metadata: bool = False,
    ) -> Data:
        method = method.upper()
        if method not in {"GET", "POST", "PATCH", "PUT", "DELETE"}:
            msg = f"Unsupported method: {method}"
            raise ValueError(msg)

        processed_body = self._process_body(body)
        redirection_history = []

        try:
            request_params = {
                "method": method,
                "url": url,
                "headers": headers,
                "timeout": timeout,
                "follow_redirects": follow_redirects,
            }
            if method in {"POST", "PATCH", "PUT", "DELETE"} and processed_body is not None:
                request_params["json"] = processed_body
            response = await client.request(**request_params)

            redirection_history = [
                {
                    "url": redirect.headers.get("Location", str(redirect.url)),
                    "status_code": redirect.status_code,
                }
                for redirect in response.history
            ]

            return await self._build_response_data(
                response,
                url,
                headers,
                redirection_history,
                save_to_file=save_to_file,
                include_httpx_metadata=include_httpx_metadata,
            )
        except (httpx.HTTPError, httpx.RequestError, httpx.TimeoutException) as exc:
            self.log(f"Error making request to {url}")
            return Data(
                data={
                    "source": url,
                    "headers": headers,
                    "status_code": 500,
                    "error": str(exc),
                    **({"redirection_history": redirection_history} if redirection_history else {}),
                },
            )

    async def _build_response_data(
        self,
        response: httpx.Response,
        source_url: str,
        headers: dict | None,
        redirection_history: list,
        *,
        save_to_file: bool = False,
        include_httpx_metadata: bool = False,
    ) -> Data:
        is_binary, file_path = await self._response_info(response, with_file_path=save_to_file)
        response_headers = self._headers_to_dict(response.headers)

        metadata = {
            "source": source_url,
            "status_code": response.status_code,
            "response_headers": response_headers,
        }

        if redirection_history:
            metadata["redirection_history"] = redirection_history

        if save_to_file:
            mode = "wb" if is_binary else "w"
            encoding = response.encoding if mode == "w" else None
            if file_path:
                await aiofiles_os.makedirs(file_path.parent, exist_ok=True)
                if is_binary:
                    async with aiofiles.open(file_path, "wb") as f:
                        await f.write(response.content)
                        await f.flush()
                else:
                    async with aiofiles.open(file_path, "w", encoding=encoding) as f:
                        await f.write(response.text)
                        await f.flush()
                metadata["file_path"] = str(file_path)

            if include_httpx_metadata:
                metadata.update({"headers": headers})
            return Data(data=metadata)

        if is_binary:
            result = response.content
        else:
            try:
                result = response.json()
            except json.JSONDecodeError:
                self.log("Failed to decode JSON response")
                result = response.text.encode("utf-8")

        metadata["result"] = result

        if include_httpx_metadata:
            metadata.update({"headers": headers})

        return Data(data=metadata)

    def add_query_params(self, url: str, params: dict) -> str:
        if not params:
            return url
        url_parts = list(urlparse(url))
        query = dict(parse_qsl(url_parts[4]))
        query.update(params)
        url_parts[4] = urlencode(query)
        return urlunparse(url_parts)

    def _headers_to_dict(self, headers: httpx.Headers) -> dict[str, str]:
        return {k.lower(): v for k, v in headers.items()}

    def _process_headers(self, headers: Any) -> dict:
        if headers is None:
            return {}
        if isinstance(headers, dict):
            return headers
        if isinstance(headers, list):
            return {item["key"]: item["value"] for item in headers if self._is_valid_key_value_item(item)}
        return {}

    async def make_api_request(self) -> Data:
        method = self.method
        url = self.url_input.strip() if isinstance(self.url_input, str) else ""
        headers = self.headers or {}
        body = self.body or {}
        timeout = self.timeout
        follow_redirects = self.follow_redirects
        save_to_file = self.save_to_file
        include_httpx_metadata = self.include_httpx_metadata

        if follow_redirects:
            self.log(
                "Security Warning: HTTP redirects are enabled. This may allow SSRF bypass attacks "
                "where a public URL redirects to internal resources (e.g., cloud metadata endpoints). "
                "Only enable this if you trust the target server."
            )

        # Normalize URL (add https:// if no protocol specified)
        url = self._normalize_url(url)

        # FIX 1: Allow localhost explicitely to bypass validators.url rejection
        parsed_url = urlparse(url)
        is_localhost = parsed_url.hostname in ("localhost", "127.0.0.1", "::1", "0.0.0.0")

        if not validators.url(url) and not is_localhost:
            msg = f"Invalid URL provided: {url}"
            raise ValueError(msg)

        # FIX 2: Bypass SSRF protection specifically if URL is localhost
        try:
            if is_localhost:
                _validated_url = url
                validated_ips = []
                self.log("SSRF Protection bypassed for localhost.")
            else:
                _validated_url, validated_ips = validate_and_resolve_url(url)
                if validated_ips:
                    self.log(f"SSRF Protection: Using DNS pinning with {len(validated_ips)} validated IP(s)")
        except SSRFProtectionError as e:
            msg = f"SSRF Protection: {e}"
            raise ValueError(msg) from e

        if isinstance(self.query_params, str):
            query_params = dict(parse_qsl(self.query_params))
        else:
            query_params = self.query_params.data if self.query_params else {}

        headers = self._process_headers(headers)
        body = self._process_body(body)
        url = self.add_query_params(url, query_params)

        if is_ssrf_protection_enabled() and follow_redirects:
            result = await self._follow_redirects_with_validation(
                method,
                url,
                headers,
                body,
                timeout,
                validated_ips,
                save_to_file=save_to_file,
                include_httpx_metadata=include_httpx_metadata,
            )
        else:
            async with self._build_http_client(url, validated_ips) as client:
                result = await self.make_request(
                    client,
                    method,
                    url,
                    headers,
                    body,
                    timeout,
                    follow_redirects=follow_redirects,
                    save_to_file=save_to_file,
                    include_httpx_metadata=include_httpx_metadata,
                )

        self.status = result
        return result

    def _build_http_client(self, url: str, validated_ips: list[str]) -> httpx.AsyncClient:
        if is_ssrf_protection_enabled() and validated_ips:
            hostname = urlparse(url).hostname
            if hostname:
                return create_ssrf_protected_client(hostname=hostname, validated_ips=validated_ips)
        return httpx.AsyncClient()

    @staticmethod
    def _method_for_redirect(method: str, status_code: int) -> str:
        method = method.upper()
        if status_code == HTTP_SEE_OTHER and method != "HEAD":
            return "GET"
        if status_code in (HTTP_MOVED_PERMANENTLY, HTTP_FOUND) and method == "POST":
            return "GET"
        return method

    @staticmethod
    def _headers_for_redirect(headers: dict | None, current_url: str, next_url: str) -> dict | None:
        if not headers:
            return headers
        current, nxt = urlparse(current_url), urlparse(next_url)
        current_port = current.port or DEFAULT_SCHEME_PORTS.get(current.scheme)
        next_port = nxt.port or DEFAULT_SCHEME_PORTS.get(nxt.scheme)
        same_origin = (current.scheme, current.hostname, current_port) == (nxt.scheme, nxt.hostname, next_port)
        https_upgrade = (
            current.hostname == nxt.hostname
            and current.scheme == "http"
            and nxt.scheme == "https"
            and current_port == DEFAULT_SCHEME_PORTS["http"]
            and next_port == DEFAULT_SCHEME_PORTS["https"]
        )
        if same_origin or https_upgrade:
            return headers
        sensitive = {"authorization", "proxy-authorization", "cookie"}
        return {k: v for k, v in headers.items() if k.lower() not in sensitive}

    async def _follow_redirects_with_validation(
        self,
        method: str,
        url: str,
        headers: dict | None,
        body: Any,
        timeout: int,
        validated_ips: list[str],
        *,
        save_to_file: bool = False,
        include_httpx_metadata: bool = False,
    ) -> Data:
        method = method.upper()
        if method not in {"GET", "POST", "PATCH", "PUT", "DELETE"}:
            msg = f"Unsupported method: {method}"
            raise ValueError(msg)

        processed_body = self._process_body(body)
        current_url = url
        current_ips = validated_ips
        redirection_history: list[dict] = []

        for _ in range(MAX_REDIRECTS + 1):
            request_params: dict[str, Any] = {
                "method": method,
                "url": current_url,
                "headers": headers,
                "timeout": timeout,
                "follow_redirects": False,
            }
            if method in {"POST", "PATCH", "PUT", "DELETE"} and processed_body is not None:
                request_params["json"] = processed_body

            try:
                async with self._build_http_client(current_url, current_ips) as client:
                    response = await client.request(**request_params)
            except (httpx.HTTPError, httpx.RequestError, httpx.TimeoutException) as exc:
                self.log(f"Error making request to {current_url}")
                return Data(
                    data={
                        "source": url,
                        "headers": headers,
                        "status_code": 500,
                        "error": str(exc),
                        **({"redirection_history": redirection_history} if redirection_history else {}),
                    },
                )

            location = response.headers.get("Location")
            if response.status_code in REDIRECT_STATUS_CODES and location:
                next_url = urljoin(current_url, location)
                redirection_history.append({"url": location, "status_code": response.status_code})

                # FIX 3: Bypass SSRF validation for localhost on redirects
                try:
                    is_next_localhost = urlparse(next_url).hostname in ("localhost", "127.0.0.1", "::1", "0.0.0.0")
                    if is_next_localhost:
                        current_ips = []
                    else:
                        _validated_url, current_ips = validate_and_resolve_url(next_url)
                except SSRFProtectionError as e:
                    msg = f"SSRF Protection: blocked redirect to {next_url}: {e}"
                    raise ValueError(msg) from e

                method = self._method_for_redirect(method, response.status_code)
                headers = self._headers_for_redirect(headers, current_url, next_url)
                current_url = next_url
                continue

            return await self._build_response_data(
                response,
                url,
                headers,
                redirection_history,
                save_to_file=save_to_file,
                include_httpx_metadata=include_httpx_metadata,
            )

        msg = f"SSRF Protection: exceeded the maximum of {MAX_REDIRECTS} redirects while requesting {url}"
        raise ValueError(msg)

    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:
        if field_name != "mode":
            if field_name == "curl_input" and self.mode == "cURL" and self.curl_input:
                return self.parse_curl(self.curl_input, build_config)
            return build_config

        if field_value == "cURL":
            set_field_display(build_config, "curl_input", value=True)
            if build_config["curl_input"]["value"]:
                try:
                    build_config = self.parse_curl(build_config["curl_input"]["value"], build_config)
                except ValueError as e:
                    self.log(f"Failed to parse cURL input: {e}")
        else:
            set_field_display(build_config, "curl_input", value=False)

        return set_current_fields(
            build_config=build_config,
            action_fields=MODE_FIELDS,
            selected_action=field_value,
            default_fields=DEFAULT_FIELDS,
            func=set_field_advanced,
            default_value=True,
        )

    async def _response_info(
        self, response: httpx.Response, *, with_file_path: bool = False
    ) -> tuple[bool, Path | None]:
        content_type = response.headers.get("Content-Type", "")
        is_binary = "application/octet-stream" in content_type or "application/binary" in content_type

        if not with_file_path:
            return is_binary, None

        component_temp_dir = Path(tempfile.gettempdir()) / self.__class__.__name__

        await aiofiles_os.makedirs(component_temp_dir, exist_ok=True)

        filename = None
        if "Content-Disposition" in response.headers:
            content_disposition = response.headers["Content-Disposition"]
            filename_match = re.search(r'filename="(.+?)"', content_disposition)
            if filename_match:
                normalized_filename = filename_match.group(1).replace("\\", "/").replace("\x00", "")
                extracted_filename = Path(normalized_filename).name
                if extracted_filename and extracted_filename not in (".", ".."):
                    filename = extracted_filename

        if not filename:
            url_path = urlparse(str(response.request.url) if response.request else "").path
            base_name = Path(url_path).name 
            if not base_name:
                base_name = "response"

            content_type_to_extension = {
                "text/plain": ".txt",
                "application/json": ".json",
                "image/jpeg": ".jpg",
                "image/png": ".png",
                "application/octet-stream": ".bin",
            }
            extension = content_type_to_extension.get(content_type, ".bin" if is_binary else ".txt")
            filename = f"{base_name}{extension}"

        file_path = component_temp_dir / filename

        if not file_path.resolve().is_relative_to(component_temp_dir.resolve()):
            msg = "Resolved output path escapes the component temporary directory"
            raise ValueError(msg)

        try:
            async with aiofiles.open(file_path, "x") as _:
                pass 
        except FileExistsError:
            timestamp = datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S%f")
            file_path = component_temp_dir / f"{timestamp}-{filename}"

        return is_binary, file_path

from langflow.custom import Component
from langflow.io import Output, DataInput, TableInput
from langflow.schema import Data, Message
import pandas as pd
from typing import Any
import json

# ==========================================
# 1. HELPER CLASSES UNTUK DYNAMIC PARSING
# ==========================================

class SafeFallback(str):
    """Mengembalikan string kosong secara aman jika data terdalam tidak ditemukan."""
    def __getattr__(self, name: str) -> 'SafeFallback':
        return SafeFallback("")

    def __getitem__(self, key: Any) -> 'SafeFallback':
        return SafeFallback("")

class DeepParsedList(list):
    """Memungkinkan akses array index menggunakan dot-notation: {output.0.id}"""
    def __getattr__(self, index: str) -> Any:
        try:
            idx = int(index)
            return self[idx]
        except (ValueError, IndexError):
            return SafeFallback("")

    def __getitem__(self, index: Any) -> Any:
        try:
            return super().__getitem__(index)
        except (IndexError, TypeError):
            return SafeFallback("")

def _recursive_wrap(data: Any) -> Any:
    """Membungkus list dan dict agar bisa diparse mendalam."""
    if isinstance(data, dict):
        return DeepParsedDict(data)
    elif isinstance(data, list):
        return DeepParsedList([_recursive_wrap(i) for i in data])
    # Langflow Data Unpacker
    elif hasattr(data, "data") and isinstance(data.data, dict):
        return _recursive_wrap(data.data)
    return data

class DeepParsedDict(dict):
    """Dictionary dengan akses dot-notation tanpa batas kedalaman."""
    def __init__(self, data_map: dict):
        super().__init__()
        if not isinstance(data_map, dict):
            return

        for k, v in data_map.items():
            self[k] = _recursive_wrap(v)

    def __getattr__(self, key: str) -> Any:
        val = self.get(key)
        return SafeFallback("") if val is None else val

    def __missing__(self, key: str) -> Any:
        return SafeFallback("")


# ==========================================
# 2. KOMPONEN UTAMA
# ==========================================

class AstraDynamicParserFilterComponent(Component):
    display_name = "Dynamic Parser"
    description = "Menerima input lalu membangun filter secara dinamis. Mendukung array indexing (.0.) dengan output JSON, Data, atau Message."
    icon = "table"

    inputs = [
        DataInput(
            name="input_data",
            display_name="Input Data (Upstream)",
            info="Hubungkan node sebelumnya (Data, Message, dict, list/tabel, DataFrame).",
            input_types=["Message", "Data", "dict", "str", "list", "DataFrame"],
            required=False,
        ),
        TableInput(
            name="filter_table",
            display_name="Filter Parameters",
            info="Gunakan format template bersarang seperti {output.0.document_id} atau {document_id}",
            table_schema=[
                {
                    "name": "key",
                    "display_name": "Metadata Key",
                    "type": "str",
                },
                {
                    "name": "value",
                    "display_name": "Metadata Value",
                    "type": "str",
                },
            ],
            value=[],
            is_list=True,
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="JSON Dict", name="json_output", method="build_json"),
        Output(display_name="Table (Data)", name="data_output", method="build_data"),
        Output(display_name="Message Text", name="message_output", method="build_message"),
    ]

    def _extract_source_data(self) -> dict:
        source_dict = {}
        target_input = self.input_data

        if not target_input:
            return source_dict

        def try_parse_json(val: Any) -> Any:
            if isinstance(val, str):
                val_stripped = val.strip()
                if val_stripped.startswith(("{", "[")):
                    try:
                        return json.loads(val_stripped)
                    except Exception:
                        pass
            return val

        target_input = try_parse_json(target_input)

        # ========================================================
        # INTI PERBAIKAN: Menyamakan struktur Data sesuai layar UI
        # ========================================================
        match target_input:
            # 1. Jika data dari Table Operations (Pandas DataFrame)
            case _ if isinstance(target_input, pd.DataFrame) or type(target_input).__name__ == "DataFrame":
                records = target_input.to_dict(orient="records")
                source_dict["tabel"] = records
                source_dict["list"] = records
                # JAWABAN DARI MASALAH ANDA: Buatkan key 'output' 
                # agar {output.0.document_id} bisa terbaca dengan sempurna.
                source_dict["output"] = records 

                # Pasang data pertama di root agar {document_id} juga jalan
                if records:
                    source_dict.update(records[0])

            # 2. Jika data dari port yang mengirim List
            case list():
                clean_list = []
                for item in target_input:
                    if hasattr(item, "data") and isinstance(item.data, dict):
                        clean_list.append(item.data)
                    elif isinstance(item, dict):
                        clean_list.append(item)
                    else:
                        clean_list.append(item)

                source_dict["tabel"] = clean_list
                source_dict["list"] = clean_list
                source_dict["output"] = clean_list # Buatkan key 'output'

                if len(clean_list) > 0 and isinstance(clean_list[0], dict):
                    source_dict.update(clean_list[0])

            # 3. Jika berupa Langflow Data Object
            case _ if hasattr(target_input, "data") and isinstance(target_input.data, dict):
                source_dict.update(target_input.data)
                source_dict["data"] = dict(target_input.data)
                source_dict["output"] = [dict(target_input.data)] # Wrap ke dalam list

            # 4. Jika murni dictionary
            case dict():
                source_dict.update(target_input)
                # Jika kebetulan dia tidak punya "output", kita jadikan dirinya sbg isi output
                if "output" not in source_dict:
                    source_dict["output"] = [target_input]

            # 5. Jika Message dari Langflow LLM
            case _:
                text_content = ""
                if hasattr(target_input, "text") and isinstance(target_input.text, str):
                    text_content = target_input.text
                elif hasattr(target_input, "content") and isinstance(target_input.content, str):
                    text_content = target_input.content
                elif isinstance(target_input, str):
                    text_content = target_input

                if text_content:
                    parsed_text = try_parse_json(text_content)
                    if isinstance(parsed_text, dict):
                        source_dict.update(parsed_text)
                    elif isinstance(parsed_text, list):
                        source_dict["output"] = parsed_text
                        if len(parsed_text) > 0 and isinstance(parsed_text[0], dict):
                            source_dict.update(parsed_text[0])
                    else:
                        source_dict["text"] = text_content

        if "text" in source_dict and "prompt" not in source_dict:
            source_dict["prompt"] = source_dict["text"]

        return source_dict

    def _generate_parsed_dict(self) -> dict:
        source_data = self._extract_source_data()
        formatted_source = DeepParsedDict(source_data)
        result_filter = {}

        if not self.filter_table:
            return result_filter

        for row in self.filter_table:
            if isinstance(row, dict) and "key" in row and "value" in row:
                raw_k = str(row.get("key") or "").strip()
                v = row.get("value", "")

                if not raw_k:
                    continue

                k = raw_k
                if "{" in k and "}" in k:
                    try:
                        k = k.format_map(formatted_source)
                    except Exception:
                        k = raw_k

                k = k.strip()
                if not k:
                    continue

                formatted_val = v
                if isinstance(v, str):
                    v_trimmed = v.strip()
                    if "{" in v_trimmed and "}" in v_trimmed:
                        try:
                            formatted_val = v_trimmed.format_map(formatted_source)
                        except Exception:
                            formatted_val = v_trimmed

                    if isinstance(formatted_val, str):
                        val_lower = formatted_val.lower()
                        if val_lower == "true":
                            formatted_val = True
                        elif val_lower == "false":
                            formatted_val = False
                        elif val_lower in ("null", "none"):
                            formatted_val = None
                        elif formatted_val.isdigit():
                            formatted_val = int(formatted_val)

                result_filter[k] = formatted_val

        return result_filter

    def build_json(self) -> dict:
        return self._generate_parsed_dict()

    def build_data(self) -> Data:
        return Data(data=self._generate_parsed_dict())

    def build_message(self) -> Message:
        return Message(text=json.dumps(self._generate_parsed_dict(), indent=2))
